from typing import Optional


class StringProcessor:
    """Utility methods for string manipulation."""

    def reverse_words(self, s: str) -> str:
        """Reverse the order of words, collapsing multiple spaces to one."""
        return ' '.join(s.split()[::-1])

    def count_vowels(self, s: str) -> int:
        """Count vowels (a, e, i, o, u), case-insensitive."""
        return sum(1 for c in s.lower() if c in 'aeiou')

    def is_palindrome(self, s: str) -> bool:
        """Check if s is a palindrome ignoring case, spaces, and punctuation."""
        cleaned = ''.join(c for c in s.lower() if c.isalnum())
        return cleaned == cleaned[::-1]

    def caesar_cipher(self, s: str, shift: int) -> str:
        """Shift letters by `shift` positions (wraps around); non-letters unchanged."""
        shift = shift % 26
        out = []
        for c in s:
            if 'a' <= c <= 'z':
                out.append(chr((ord(c) - 97 + shift) % 26 + 97))
            elif 'A' <= c <= 'Z':
                out.append(chr((ord(c) - 65 + shift) % 26 + 65))
            else:
                out.append(c)
        return ''.join(out)

    def most_common_word(self, s: str) -> Optional[str]:
        """Return the most frequent word (case-insensitive); tie -> first occurrence."""
        words = s.split()
        if not words:
            return None
        counts = {}
        for w in words:
            key = w.lower()
            counts[key] = counts.get(key, 0) + 1
        max_count = max(counts.values())
        for w in words:
            if counts[w.lower()] == max_count:
                return w
        return None  # unreachable
```

